CREATE TRIGGER json_completion_markers_evidence_insert BEFORE INSERT ON completion_markers
WHEN NEW.evidence IS NOT NULL AND CASE WHEN NOT json_valid(NEW.evidence) THEN 1 WHEN json_type(NEW.evidence)<>'object' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(NEW.evidence) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR (json_type(NEW.evidence,'$.current_page_collections') IS NOT NULL AND (json_type(NEW.evidence,'$.current_page_collections')<>'array' OR EXISTS(SELECT 1 FROM json_each(NEW.evidence,'$.current_page_collections') m WHERE CASE WHEN m.type<>'object' THEN 1 ELSE ((SELECT count(*) FROM json_each(m.value))<>2 OR coalesce(json_type(m.value,'$.fetch_collection_id'),'')<>'text' OR coalesce(json_type(m.value,'$.page_ordinals'),'')<>'array' OR coalesce(json_array_length(m.value,'$.page_ordinals'),0)=0 OR EXISTS(SELECT 1 FROM json_each(m.value,'$.page_ordinals') e WHERE e.type<>'integer' OR e.value<>CAST(e.key AS INTEGER))) END) OR EXISTS(SELECT 1 FROM json_each(NEW.evidence,'$.current_page_collections') m GROUP BY CASE WHEN m.type='object' THEN json_extract(m.value,'$.fetch_collection_id') END HAVING count(*)>1)))
 OR (json_type(NEW.evidence,'$.terminal') IS NOT NULL AND json_type(NEW.evidence,'$.terminal') NOT IN ('true','false'))
 OR (json_type(NEW.evidence,'$.context_proven') IS NOT NULL AND json_type(NEW.evidence,'$.context_proven') NOT IN ('true','false'))
 OR (json_type(NEW.evidence,'$.status') IS NOT NULL AND (json_type(NEW.evidence,'$.status')<>'integer' OR json_extract(NEW.evidence,'$.status') NOT BETWEEN 100 AND 599))
