CREATE TRIGGER json_fetch_occurrences_request_insert BEFORE INSERT ON fetch_occurrences
WHEN NEW.request IS NOT NULL AND CASE WHEN NOT json_valid(NEW.request) THEN 1 WHEN json_type(NEW.request)<>'object' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(NEW.request) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR (json_type(NEW.request,'$.thread') IS NOT NULL AND (json_type(NEW.request,'$.thread')<>'text' OR length(json_extract(NEW.request,'$.thread'))=0))
 OR (json_type(NEW.request,'$.review_thread_provider_resource_id') IS NOT NULL AND (json_type(NEW.request,'$.review_thread_provider_resource_id')<>'text' OR length(json_extract(NEW.request,'$.review_thread_provider_resource_id'))=0))
 OR (json_type(NEW.request,'$.query') IS NOT NULL AND (json_type(NEW.request,'$.query')<>'text' OR length(json_extract(NEW.request,'$.query'))=0))
 OR (json_type(NEW.request,'$.url') IS NOT NULL AND (json_type(NEW.request,'$.url')<>'text' OR length(json_extract(NEW.request,'$.url'))=0))
 OR (json_type(NEW.request,'$.method') IS NOT NULL AND (json_type(NEW.request,'$.method')<>'text' OR length(json_extract(NEW.request,'$.method'))=0))
 OR (json_type(NEW.request,'$.variables') IS NOT NULL AND json_type(NEW.request,'$.variables')<>'object')
 OR (json_type(NEW.request,'$.variables.thread') IS NOT NULL AND (json_type(NEW.request,'$.variables.thread')<>'text' OR length(json_extract(NEW.request,'$.variables.thread'))=0))
 OR (json_type(NEW.request,'$.variables.owner') IS NOT NULL AND (json_type(NEW.request,'$.variables.owner')<>'text' OR length(json_extract(NEW.request,'$.variables.owner'))=0))
 OR (json_type(NEW.request,'$.variables.name') IS NOT NULL AND (json_type(NEW.request,'$.variables.name')<>'text' OR length(json_extract(NEW.request,'$.variables.name'))=0))
 OR (json_type(NEW.request,'$.variables.cursor') IS NOT NULL AND json_type(NEW.request,'$.variables.cursor') NOT IN ('text','null'))
 OR (json_type(NEW.request,'$.variables.commentCursor') IS NOT NULL AND json_type(NEW.request,'$.variables.commentCursor') NOT IN ('text','null'))
 OR (json_type(NEW.request,'$.variables.number') IS NOT NULL AND (json_type(NEW.request,'$.variables.number')<>'integer' OR json_extract(NEW.request,'$.variables.number')<=0 OR json_extract(NEW.request,'$.variables.number')>9223372036854775807))
 OR (json_type(NEW.request,'$.variables.pageSize') IS NOT NULL AND (json_type(NEW.request,'$.variables.pageSize')<>'integer' OR json_extract(NEW.request,'$.variables.pageSize')<=0 OR json_extract(NEW.request,'$.variables.pageSize')>9223372036854775807))
 OR (json_type(NEW.request,'$.terminal') IS NOT NULL AND json_type(NEW.request,'$.terminal') NOT IN ('true','false'))
 OR (json_type(NEW.request,'$.context_proven') IS NOT NULL AND json_type(NEW.request,'$.context_proven') NOT IN ('true','false'))
