CREATE TRIGGER json_git_acquisitions_request_update BEFORE UPDATE ON git_acquisitions
WHEN NEW.request IS NOT NULL AND CASE WHEN NOT json_valid(NEW.request) THEN 1 WHEN json_type(NEW.request)<>'object' THEN 1 ELSE (
