CREATE TRIGGER json_review_resources_acquisition_scope_json_insert BEFORE INSERT ON review_resources
WHEN NEW.acquisition_scope_json IS NOT NULL AND CASE WHEN NOT json_valid(NEW.acquisition_scope_json) THEN 1 WHEN json_type(NEW.acquisition_scope_json)<>'object' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(NEW.acquisition_scope_json) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR coalesce(json_type(NEW.acquisition_scope_json),'')<>'object'
 OR EXISTS(SELECT 1 FROM json_tree(NEW.acquisition_scope_json) j WHERE j.key IN ('fetch_occurrence_uuidv4','fetch_occurrence_uuidv4s','parsed_result_uuidv4','parsed_result_uuidv4s','parser_profile_uuidv4','parser_profile_verification_uuidv4','payload','selection_decision_uuidv4','selection_predecessors','source_input_uuidv4'))
 OR (json_type(NEW.acquisition_scope_json,'$.parser_module') IS NOT NULL AND (json_type(NEW.acquisition_scope_json,'$.parser_module')<>'text' OR length(json_extract(NEW.acquisition_scope_json,'$.parser_module'))=0 OR instr(json_extract(NEW.acquisition_scope_json,'$.parser_module'),char(0))>0))
 OR (json_type(NEW.acquisition_scope_json,'$.parser_version') IS NOT NULL AND (json_type(NEW.acquisition_scope_json,'$.parser_version')<>'text' OR length(json_extract(NEW.acquisition_scope_json,'$.parser_version'))=0 OR instr(json_extract(NEW.acquisition_scope_json,'$.parser_version'),char(0))>0))
 OR coalesce(json_type(NEW.acquisition_scope_json,'$.repository_uuidv4'),'')<>'text' OR NOT (length(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'))=36 AND length(CAST(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4') AS BLOB))=36 AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),9,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),14,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),19,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),24,1)='-' AND length(replace(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),'-',''))=32 AND replace(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),15,1)='4' AND substr(json_extract(NEW.acquisition_scope_json,'$.repository_uuidv4'),20,1) IN ('8','9','a','b'))
 OR coalesce(json_type(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),'')<>'text' OR NOT (length(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'))=36 AND length(CAST(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4') AS BLOB))=36 AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),9,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),14,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),19,1)='-' AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),24,1)='-' AND length(replace(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),'-',''))=32 AND replace(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),15,1)='4' AND substr(json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4'),20,1) IN ('8','9','a','b')) OR json_extract(NEW.acquisition_scope_json,'$.service_instance_uuidv4') IS NOT NEW.service_instance_uuidv4
